-- 한강뷰 드림 Auto Stock V4.5 · 원본 보존 · 신규 분리 검증 · 기본 중지
local encoded = [==[]==]
local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
local numbers = {} for i=1,#alphabet do numbers[alphabet:sub(i,i)]=i-1 end
local dictionary, nextCode, previous, out = {}, 256, nil, {}
local function reset() dictionary={} for i=0,255 do dictionary[i]=string.char(i) end nextCode=256 end
reset()
for i=1,#encoded,2 do
	local code=numbers[encoded:sub(i,i)]*62+numbers[encoded:sub(i+1,i+1)]
	local word=dictionary[code] or (previous and previous..previous:sub(1,1))
	assert(word,"UI 압축 복원 실패")
	out[#out+1]=word
	if previous then
		if nextCode<3844 then dictionary[nextCode]=previous..word:sub(1,1); nextCode=nextCode+1
		else reset() end
	end
	previous=word
end
local source=table.concat(out)

local run = assert(loadstring(source, "한강뷰 V4.5"))
if setfenv then setfenv(run, getfenv()) end
return run(...)
